for r in range(R):
    cs=[c for c,v in enumerate(g[r]) if v==3]
    if len(cs)>1:
        for c in range(min(cs),max(cs)+1):
            if out[r][c]==1: out[r][c]=2
for c in range(C):
    rs=[r for r in range(R) if g[r][c]==3]
    if len(rs)>1:
        for r in range(min(rs),max(rs)+1):
            if out[r][c]==1: out[r][c]=2
print(json.dumps(out,separators=(',',':')))

